public void testSetFilterIncrementToken() throws IOException {
    CharArraySet set = new CharArraySet(5, true);
    set.add("lucenefox");
    String[] output = new String[] { "the", "quick", "brown", "LuceneFox", "jumps" };
    assertTokenStreamContents(new LowerCaseFilterMock(new SetKeywordMarkerFilter(whitespaceMockTokenizer("The quIck browN LuceneFox Jumps"), set)), output);
    CharArraySet mixedCaseSet = new CharArraySet(asSet("LuceneFox"), false);
    assertTokenStreamContents(new LowerCaseFilterMock(new SetKeywordMarkerFilter(whitespaceMockTokenizer("The quIck browN LuceneFox Jumps"), mixedCaseSet)), output);
    CharArraySet set2 = set;
    assertTokenStreamContents(new LowerCaseFilterMock(new SetKeywordMarkerFilter(whitespaceMockTokenizer("The quIck browN LuceneFox Jumps"), set2)), output);
}

