    params.put("avg", "10f");
    params.put("std", "1.5f");
    final Normalizer norm = Normalizer.getInstance(solrResourceLoader, StandardNormalizer.class.getCanonicalName(), params);
    for (final float v : new float[] { 10f, 20f, 25f, 30f, 31f, 40f, 42f, 100f, 10000000f }) {
