    final String badfeature = "{\"name\": \"fvalue\", \"class\": \"" + fieldValueFeatureClassName + "\", \"params\": {\"value\": 1} }";
    assertJPut(ManagedFeatureStore.REST_END_POINT, badfeature, "/error/msg/=='No setter corrresponding to \\'value\\' in " + fieldValueFeatureClassName + "'");
