    assertJPut(ManagedModelStore.REST_END_POINT, model, "/responseHeader/status==400");
    // success
    model = "{ \"name\":\"testmodel3\", \"class\":\"" + linearModelClassName + "\", \"features\":[{\"name\":\"test1\"}, {\"name\":\"test2\"}],\"params\":{\"weights\":{\"test1\":1.5,\"test2\":2.0}}}";
    assertJPut(ManagedModelStore.REST_END_POINT, model, "/responseHeader/status==0");
    // success
    final String multipleModels = "[{ \"name\":\"testmodel4\", \"class\":\"" + linearModelClassName + "\", \"features\":[{\"name\":\"test1\"}, {\"name\":\"test2\"}],\"params\":{\"weights\":{\"test1\":1.5,\"test2\":2.0}} }\n" + ",{ \"name\":\"testmodel5\", \"class\":\"" + linearModelClassName + "\", \"features\":[{\"name\":\"test1\"}, {\"name\":\"test2\"}],\"params\":{\"weights\":{\"test1\":1.5,\"test2\":2.0}} } ]";
    assertJPut(ManagedModelStore.REST_END_POINT, multipleModels, "/responseHeader/status==0");
    final String qryResult = JQ(ManagedModelStore.REST_END_POINT);
    assert (qryResult.contains("\"name\":\"testmodel3\"") && qryResult.contains("\"name\":\"testmodel4\"") && qryResult.contains("\"name\":\"testmodel5\""));
    assertJQ(ManagedModelStore.REST_END_POINT, "/models/[0]/name=='testmodel3'");
    assertJQ(ManagedModelStore.REST_END_POINT, "/models/[1]/name=='testmodel4'");
    assertJQ(ManagedModelStore.REST_END_POINT, "/models/[2]/name=='testmodel5'");
    restTestHarness.delete(ManagedModelStore.REST_END_POINT + "/testmodel3");
    restTestHarness.delete(ManagedModelStore.REST_END_POINT + "/testmodel4");
    restTestHarness.delete(ManagedModelStore.REST_END_POINT + "/testmodel5");
    assertJQ(ManagedModelStore.REST_END_POINT + "/" + FeatureStore.DEFAULT_FEATURE_STORE_NAME, "/models==[]'");
    assertJQ(ManagedFeatureStore.REST_END_POINT, "/featureStores==['" + TEST_FEATURE_STORE_NAME + "','" + FeatureStore.DEFAULT_FEATURE_STORE_NAME + "']");
    assertJQ(ManagedFeatureStore.REST_END_POINT + "/" + FeatureStore.DEFAULT_FEATURE_STORE_NAME, "/features/[0]/name=='test1'");
