@Test
public void testOverseerRole() throws Exception {
    logOverseerState();
    List<String> nodes = OverseerCollectionConfigSetProcessor.getSortedOverseerNodeNames(zkClient());
    String overseer1 = OverseerCollectionConfigSetProcessor.getLeaderNode(zkClient());
    nodes.remove(overseer1);
    Collections.shuffle(nodes, random());
    String overseer2 = nodes.get(0);
    log.info("### Setting overseer designate {}", overseer2);
    CollectionAdminRequest.addRole(overseer2, "overseer").process(cluster.getSolrClient());
    waitForNewOverseer(15, overseer2);
    //add another node as overseer
    nodes.remove(overseer2);
    Collections.shuffle(nodes, random());
    String overseer3 = nodes.get(0);
    log.info("### Adding another overseer designate {}", overseer3);
    CollectionAdminRequest.addRole(overseer3, "overseer").process(cluster.getSolrClient());
    // kill the current overseer, and check that the new designate becomes the new overseer
    JettySolrRunner leaderJetty = getOverseerJetty();
    logOverseerState();
    ChaosMonkey.stop(leaderJetty);
    waitForNewOverseer(10, overseer3);
    // add another node as overseer
    nodes.remove(overseer3);
    Collections.shuffle(nodes, random());
    String overseer4 = nodes.get(0);
    log.info("### Adding last overseer designate {}", overseer4);
    CollectionAdminRequest.addRole(overseer4, "overseer").process(cluster.getSolrClient());
    logOverseerState();
    // remove the overseer role from the current overseer
    CollectionAdminRequest.removeRole(overseer3, "overseer").process(cluster.getSolrClient());
    waitForNewOverseer(15, overseer4);
    // Add it back again - we now have two delegates, 4 and 3
    CollectionAdminRequest.addRole(overseer3, "overseer").process(cluster.getSolrClient());
    // explicitly tell the overseer to quit
    String leaderId = OverseerCollectionConfigSetProcessor.getLeaderId(zkClient());
    String leader = OverseerCollectionConfigSetProcessor.getLeaderNode(zkClient());
    log.info("### Sending QUIT to overseer {}", leader);
    Overseer.getStateUpdateQueue(zkClient()).offer(Utils.toJSON(new ZkNodeProps(Overseer.QUEUE_OPERATION, OverseerAction.QUIT.toLower(), "id", leaderId)));
    waitForNewOverseer(15, s -> Objects.equals(leader, s) == false);
    Thread.sleep(1000);
    logOverseerState();
    assertTrue("The old leader should have rejoined election", OverseerCollectionConfigSetProcessor.getSortedOverseerNodeNames(zkClient()).contains(leader));
}

@Test
public void test() throws Exception {
    // find existing command counts because collection may be created by base test class too
    int numCollectionCreates = 0, numOverseerCreates = 0;
    String collectionName = "overseer_status_test";
    CollectionAdminRequest.createCollection(collectionName, "conf", 1, 1).process(cluster.getSolrClient());
    NamedList<Object> resp = new CollectionAdminRequest.OverseerStatus().process(cluster.getSolrClient()).getResponse();
    NamedList<Object> collection_operations = (NamedList<Object>) resp.get("collection_operations");
    NamedList<Object> overseer_operations = (NamedList<Object>) resp.get("overseer_operations");
    SimpleOrderedMap<Object> createcollection = (SimpleOrderedMap<Object>) collection_operations.get(CollectionParams.CollectionAction.CREATE.toLower());
    assertEquals("No stats for create in OverseerCollectionProcessor", numCollectionCreates + 1, createcollection.get("requests"));
    createcollection = (SimpleOrderedMap<Object>) overseer_operations.get(CollectionParams.CollectionAction.CREATE.toLower());
    assertEquals("No stats for create in Overseer", numOverseerCreates + 1, createcollection.get("requests"));
    // Reload the collection
    CollectionAdminRequest.reloadCollection(collectionName).process(cluster.getSolrClient());
    resp = new CollectionAdminRequest.OverseerStatus().process(cluster.getSolrClient()).getResponse();
    collection_operations = (NamedList<Object>) resp.get("collection_operations");
    SimpleOrderedMap<Object> reload = (SimpleOrderedMap<Object>) collection_operations.get(CollectionParams.CollectionAction.RELOAD.toLower());
    assertEquals("No stats for reload in OverseerCollectionProcessor", 1, reload.get("requests"));
    try {
        CollectionAdminRequest.splitShard("non_existent_collection").setShardName("non_existent_shard").process(cluster.getSolrClient());
        fail("Split shard for non existent collection should have failed");
    } catch (Exception e) {
        // expected because we did not correctly specify required params for split
    }
    resp = new CollectionAdminRequest.OverseerStatus().process(cluster.getSolrClient()).getResponse();
    collection_operations = (NamedList<Object>) resp.get("collection_operations");
    SimpleOrderedMap<Object> split = (SimpleOrderedMap<Object>) collection_operations.get(CollectionParams.CollectionAction.SPLITSHARD.toLower());
    assertEquals("No stats for split in OverseerCollectionProcessor", 1, split.get("errors"));
    assertNotNull(split.get("recent_failures"));
    SimpleOrderedMap<Object> amIleader = (SimpleOrderedMap<Object>) collection_operations.get("am_i_leader");
    assertNotNull("OverseerCollectionProcessor amILeader stats should not be null", amIleader);
    assertNotNull(amIleader.get("requests"));
    assertTrue(Integer.parseInt(amIleader.get("requests").toString()) > 0);
    assertNotNull(amIleader.get("errors"));
    assertNotNull(amIleader.get("avgTimePerRequest"));
    amIleader = (SimpleOrderedMap<Object>) overseer_operations.get("am_i_leader");
    assertNotNull("Overseer amILeader stats should not be null", amIleader);
    assertNotNull(amIleader.get("requests"));
    assertTrue(Integer.parseInt(amIleader.get("requests").toString()) > 0);
    assertNotNull(amIleader.get("errors"));
    assertNotNull(amIleader.get("avgTimePerRequest"));
    SimpleOrderedMap<Object> updateState = (SimpleOrderedMap<Object>) overseer_operations.get("update_state");
    assertNotNull("Overseer update_state stats should not be null", updateState);
    assertNotNull(updateState.get("requests"));
    assertTrue(Integer.parseInt(updateState.get("requests").toString()) > 0);
    assertNotNull(updateState.get("errors"));
    assertNotNull(updateState.get("avgTimePerRequest"));
}

@Test
public void testContainsTaskWithRequestId() throws Exception {
    String tqZNode = "/taskqueue/test";
    String requestId = "foo";
    String nonExistentRequestId = "bar";
    OverseerTaskQueue tq = makeDistributedQueue(tqZNode);
    // Basic ops
    // Put an expected Overseer task onto the queue
    final Map<String, Object> props = new HashMap<>();
    props.put(CommonParams.NAME, "coll1");
    props.put(OverseerCollectionMessageHandler.COLL_CONF, "myconf");
    props.put(OverseerCollectionMessageHandler.NUM_SLICES, 1);
    props.put(ZkStateReader.REPLICATION_FACTOR, 3);
    props.put(CommonAdminParams.ASYNC, requestId);
    tq.offer(Utils.toJSON(props));
    assertTrue("Task queue should contain task with requestid " + requestId, tq.containsTaskWithRequestId(CommonAdminParams.ASYNC, requestId));
    assertFalse("Task queue should not contain task with requestid " + nonExistentRequestId, tq.containsTaskWithRequestId(CommonAdminParams.ASYNC, nonExistentRequestId));
    // Create a response node as if someone is waiting for a response from the Overseer; then,
    // create the request node.
    // Here we're reaching a bit into the internals of OverseerTaskQueue in order to create the same
    // response node structure but without setting a watch on it and removing it immediately when
    // a response is set, in order to artificially create the race condition that
    // containsTaskWithRequestId runs while the response is still in the queue.
    String watchID = tq.createResponseNode();
    String requestId2 = "baz";
    props.put(CommonAdminParams.ASYNC, requestId2);
    tq.createRequestNode(Utils.toJSON(props), watchID);
    // Set a SolrResponse as the response node by removing the QueueEvent, as done in OverseerTaskProcessor
    List<OverseerTaskQueue.QueueEvent> queueEvents = tq.peekTopN(2, s -> false, 1000);
    OverseerTaskQueue.QueueEvent requestId2Event = null;
    for (OverseerTaskQueue.QueueEvent queueEvent : queueEvents) {
        Map<String, Object> eventProps = (Map<String, Object>) Utils.fromJSON(queueEvent.getBytes());
        if (requestId2.equals(eventProps.get(CommonAdminParams.ASYNC))) {
            requestId2Event = queueEvent;
            break;
        }
    }
    assertNotNull("Didn't find event with requestid " + requestId2, requestId2Event);
    requestId2Event.setBytes(SolrResponse.serializable(new SolrResponseBase()));
    tq.remove(requestId2Event);
    // Make sure this call to check if requestId exists doesn't barf with Json parse exception
    assertTrue("Task queue should contain task with requestid " + requestId, tq.containsTaskWithRequestId(CommonAdminParams.ASYNC, requestId));
}

