@Test
public void test() throws Exception {
    CloudSolrClient solrClient = cluster.getSolrClient();
    solrClient.setDefaultCollection(COLLECTION_NAME);
    for (int i = 0; i < 10; i++) {
        SolrInputDocument doc = new SolrInputDocument();
        doc.addField("id", String.valueOf(i));
        solrClient.add(doc);
    }
    solrClient.commit();
    // find the leader node
    Replica replica = solrClient.getZkStateReader().getLeaderRetry(COLLECTION_NAME, "shard1");
    JettySolrRunner replicaJetty = null;
    List<JettySolrRunner> jettySolrRunners = cluster.getJettySolrRunners();
    for (JettySolrRunner jettySolrRunner : jettySolrRunners) {
        int port = jettySolrRunner.getBaseUrl().getPort();
        if (replica.getStr(BASE_URL_PROP).contains(":" + port)) {
            replicaJetty = jettySolrRunner;
            break;
        }
    }
    // kill the leader
    ChaosMonkey.kill(replicaJetty);
    // add a replica (asynchronously)
    CollectionAdminRequest.AddReplica addReplica = CollectionAdminRequest.addReplicaToShard(COLLECTION_NAME, "shard1");
    String asyncId = addReplica.processAsync(solrClient);
    // wait a bit
    Thread.sleep(1000);
    // bring the old leader node back up
    ChaosMonkey.start(replicaJetty);
    // wait until everyone is active
    solrClient.waitForState(COLLECTION_NAME, DEFAULT_TIMEOUT, TimeUnit.SECONDS, (n, c) -> DocCollection.isFullyActive(n, c, 1, 2));
    // now query each replica and check for consistency
    assertConsistentReplicas(solrClient, solrClient.getZkStateReader().getClusterState().getSlice(COLLECTION_NAME, "shard1"));
    // sanity check that documents still exist
    QueryResponse response = solrClient.query(new SolrQuery("*:*"));
    assertEquals("Indexed documents not found", 10, response.getResults().getNumFound());
}

@Test
public void testLeaderElectionWithZkExpiry() throws Exception {
    String zkDir = createTempDir("zkData").toFile().getAbsolutePath();
    Path ccDir = createTempDir("testLeaderElectionWithZkExpiry-solr");
    CoreContainer cc = createCoreContainer(ccDir, SOLRXML);
    final ZkTestServer server = new ZkTestServer(zkDir);
    server.setTheTickTime(1000);
    SolrZkClient zc = null;
    try {
        server.run();
        AbstractZkTestCase.tryCleanSolrZkNode(server.getZkHost());
        AbstractZkTestCase.makeSolrZkNode(server.getZkHost());
        CloudConfig cloudConfig = new CloudConfig.CloudConfigBuilder("dummy.host.com", 8984, "solr").setLeaderConflictResolveWait(180000).setLeaderVoteWait(180000).build();
        final ZkController zkController = new ZkController(cc, server.getZkAddress(), 15000, cloudConfig, new CurrentCoreDescriptorProvider() {

            @Override
            public List<CoreDescriptor> getCurrentDescriptors() {
                return Collections.EMPTY_LIST;
            }
        });
        try {
            Thread killer = new Thread() {

                @Override
                public void run() {
                    long timeout = System.nanoTime() + TimeUnit.NANOSECONDS.convert(10, TimeUnit.SECONDS);
                    while (System.nanoTime() < timeout) {
                        long sessionId = zkController.getZkClient().getSolrZooKeeper().getSessionId();
                        server.expire(sessionId);
                        try {
                            Thread.sleep(10);
                        } catch (InterruptedException e) {
                        }
                    }
                }
            };
            killer.start();
            killer.join();
            long timeout = System.nanoTime() + TimeUnit.NANOSECONDS.convert(60, TimeUnit.SECONDS);
            zc = new SolrZkClient(server.getZkAddress(), LeaderElectionTest.TIMEOUT);
            boolean found = false;
            while (System.nanoTime() < timeout) {
                try {
                    String leaderNode = OverseerCollectionConfigSetProcessor.getLeaderNode(zc);
                    if (leaderNode != null && !leaderNode.trim().isEmpty()) {
                        log.info("Time={} Overseer leader is = {}", System.nanoTime(), leaderNode);
                        found = true;
                        break;
                    }
                } catch (KeeperException.NoNodeException nne) {
                    // ignore
                }
            }
            assertTrue(found);
        } finally {
            zkController.close();
        }
    } finally {
        if (zc != null)
            zc.close();
        cc.shutdown();
        server.shutdown();
    }
}

