                } catch (javax.management.AttributeNotFoundException e) {
                    throw new RuntimeException("Unable to featch attribute for " + o.getObjectName() + ": " + attr.getName(), e);
                }
            }
        }
    }
    assertTrue("No SolrDynamicMBeans found", 0 < numDynamicMbeans);
}

