@Test
public void testQueryToString() throws Exception {
    // test that both boosts are represented in a double-boost scenario
    assertQ(req("debugQuery", "true", "indent", "true", "rows", "0", "q", "(foo_s:aaa^3)^4"), "//str[@name='parsedquery'][.='foo_s:aaa^3.0^4.0']");
    // test to see that extra parens are avoided
    assertQ(req("debugQuery", "true", "indent", "true", "rows", "0", "q", "+foo_s:aaa^3 -bar_s:bbb^0"), "//str[@name='parsedquery'][.='+foo_s:aaa^3.0 -bar_s:bbb^0.0']");
    // test that parens are added when needed
    assertQ(req("debugQuery", "true", "indent", "true", "rows", "0", "q", "foo_s:aaa (bar_s:bbb baz_s:ccc)"), "//str[@name='parsedquery'][.='foo_s:aaa (bar_s:bbb baz_s:ccc)']");
    // test boosts on subqueries
    assertQ(req("debugQuery", "true", "indent", "true", "rows", "0", "q", "foo_s:aaa^3 (bar_s:bbb baz_s:ccc)^4"), "//str[@name='parsedquery'][.='foo_s:aaa^3.0 (bar_s:bbb baz_s:ccc)^4.0']");
    // test constant score query boost exists
    assertQ(req("debugQuery", "true", "indent", "true", "rows", "0", "q", "foo_s:aaa^=3"), "//str[@name='parsedquery'][contains(.,'3.0')]");
}

