        h.close();
        // Stop the dictionary's input iterator
        System.clearProperty(RandomTestDictionaryFactory.RandomTestDictionary.getEnabledSysProp("longRandomAnalyzingInfixSuggester"));
        job.get();
    } finally {
        ExecutorUtil.shutdownAndAwaitTermination(executor);
