            docFields[j++] = "test_is";
            docFields[j++] = String.valueOf(random().nextInt(cardinality));
            docFields[j++] = "test_ls";
            docFields[j++] = String.valueOf(random().nextInt(cardinality));
            docFields[j++] = "test_fs";
