    //all docs with values
    assertQ(req("fl", "" + FIELD_NAME, "q", FIELD_NAME + ":[* TO *]"), "//*[@numFound='15']");
    //empty docs
    assertQ(req("fl", "" + FIELD_NAME, "q", "-" + FIELD_NAME + ":[* TO *]"), "//*[@numFound='2']");
}

