    assertJQ(req("defType", "func", "q", "geodist(1.0,2,3,4.0)", "fq", "id:100", "fl", "id,score"), 1e-5, "/response/docs/[0]/score==314.40338");
    // default to reading pt
    assertJQ(req("defType", "func", "q", "geodist(1,2)", "pt", "3,4", "fq", "id:100", "fl", "id,score"), 1e-5, "/response/docs/[0]/score==314.40338");
    // default to reading pt first
    assertJQ(req("defType", "func", "q", "geodist(1,2)", "pt", "3,4", "sfield", "store", "fq", "id:100", "fl", "id,score"), 1e-5, "/response/docs/[0]/score==314.40338");
    // if pt missing, use sfield
    assertJQ(req("defType", "func", "q", "geodist(3,4)", "sfield", "store", "fq", "id:100", "fl", "id,score"), 1e-5, "/response/docs/[0]/score==314.40338");
    // if pt missing, use sfield (RPT)
    assertJQ(req("defType", "func", "q", "geodist(3,4)", "sfield", "store_rpt", "fq", "id:100", "fl", "id,score"), 1e-5, "/response/docs/[0]/score==314.40338");
    // read both pt and sfield
    assertJQ(req("defType", "func", "q", "geodist()", "pt", "3,4", "sfield", "store", "fq", "id:100", "fl", "id,score"), 1e-5, "/response/docs/[0]/score==314.40338");
    // read both pt and sfield (RPT)
    assertJQ(req("defType", "func", "q", "geodist()", "pt", "3,4", "sfield", "store_rpt", "fq", "id:100", "fl", "id,score"), 1e-5, "/response/docs/[0]/score==314.40338");
    // param substitution
    assertJQ(req("defType", "func", "q", "geodist($a,$b)", "a", "3,4", "b", "store", "fq", "id:100", "fl", "id,score"), 1e-5, "/response/docs/[0]/score==314.40338");
}

