    assertJQ(req("qt", "/get", "id", "11", "fl", "id"), "=={'doc':{'id':'11'}}");
    // multivalued field
    assertU(adoc("id", "12", "val_ls", "1", "val_ls", "2"));
    assertJQ(req("q", "id:12"), "/response/numFound==0");
    assertJQ(req("qt", "/get", "id", "12", "fl", "id,val_ls"), "=={'doc':{'id':'12', 'val_ls':[1,2]}}");
    assertU(commit());
    assertJQ(req("qt", "/get", "id", "12", "fl", "id,val_ls"), "=={'doc':{'id':'12', 'val_ls':[1,2]}}");
