    h.reload();
    assertJQ(req("qt", "/get", "id", "1"), "=={'doc':{'id':'1','_version_':" + version + "}}");
    // open a normal (caching) NRT searcher
    assertU(commit("softCommit", "true"));
    assertJQ(req("q", "id:1"), "/response/numFound==1");
    Random rand = random();
    int iter = atLeast(20);
    for (int i = 0; i < iter; i++) {
        if (rand.nextBoolean()) {
            // System.out.println("!!! add");
            version = addAndGetVersion(sdoc("id", "1"), null);
        }
        if (rand.nextBoolean()) {
            if (rand.nextBoolean()) {
                // System.out.println("!!! flush");
                // should cause a RTG searcher to be opened as well
                assertU(commit("openSearcher", "false"));
            } else {
                boolean softCommit = rand.nextBoolean();
                System.out.println("!!! softCommit" + softCommit);
                // assertU(commit("softCommit", ""+softCommit));
            }
        }
        if (rand.nextBoolean()) {
            // RTG should always be able to see the last version
            // System.out.println("!!! rtg");
            assertJQ(req("qt", "/get", "id", "1"), "=={'doc':{'id':'1','_version_':" + version + "}}");
        }
        if (rand.nextBoolean()) {
            // a normal search should always find 1 doc
            // System.out.println("!!! q");
            assertJQ(req("q", "id:1"), "/response/numFound==1");
        }
        if (rand.nextBoolean()) {
            // System.out.println("!!! reload");
            h.reload();
        }
    }
    // test framework should ensure that all searchers opened have been closed.
}

