@Test
public void testSort() throws Exception {
    assertU(adoc("id", "100", fieldName, "1,2"));
    assertU(adoc("id", "101", fieldName, "4,-1"));
    //far away from these queries
    assertU(adoc("id", "999", fieldName, "70,70"));
    assertU(commit());
    //test absence of score=distance means it doesn't score
    assertJQ(req("q", radiusQuery(3, 4, 9, null, null), "fl", "id,score"), 1e-9, "/response/docs/[0]/score==1.0", "/response/docs/[1]/score==1.0");
    //score by distance
    assertJQ(req("q", radiusQuery(3, 4, 9, "distance", null), "fl", "id,score", "sort", //want ascending due to increasing distance
    "score asc"), 1e-3, "/response/docs/[0]/id=='100'", "/response/docs/[0]/score==2.827493", "/response/docs/[1]/id=='101'", "/response/docs/[1]/score==5.089807");
    //score by recipDistance
    assertJQ(req("q", radiusQuery(3, 4, 9, "recipDistance", null), "fl", "id,score", "sort", //want descending
    "score desc"), 1e-3, "/response/docs/[0]/id=='100'", "/response/docs/[0]/score==0.3099695", "/response/docs/[1]/id=='101'", "/response/docs/[1]/score==0.19970943");
    //score by distance and don't filter
    assertJQ(req(//circle radius is small and shouldn't match either, but we disable filtering
    "q", radiusQuery(3, 4, 0.000001, "distance", "false"), "fl", "id,score", "sort", //want ascending due to increasing distance
    "score asc"), 1e-3, "/response/docs/[0]/id=='100'", "/response/docs/[0]/score==2.827493", "/response/docs/[1]/id=='101'", "/response/docs/[1]/score==5.089807");
    //query again with the query point closer to #101, and check the new ordering
    assertJQ(req("q", radiusQuery(4, 0, 9, "distance", null), "fl", "id,score", "sort", //want ascending due to increasing distance
    "score asc"), 1e-4, "/response/docs/[0]/id=='101'", "/response/docs/[1]/id=='100'");
    //use sort=query(...)
    assertJQ(req(//exclude that doc
    "q", //exclude that doc
    "-id:999", "fl", "id,score", //want ascending due to increasing distance
    "sort", //want ascending due to increasing distance
    "query($sortQuery) asc", "sortQuery", radiusQuery(3, 4, 9, "distance", null)), 1e-4, "/response/docs/[0]/id=='100'", "/response/docs/[1]/id=='101'");
    //check reversed direction with query point closer to #101
    assertJQ(req(//exclude that doc
    "q", //exclude that doc
    "-id:999", "fl", "id,score", //want ascending due to increasing distance
    "sort", //want ascending due to increasing distance
    "query($sortQuery) asc", "sortQuery", radiusQuery(4, 0, 9, "distance", null)), 1e-4, "/response/docs/[0]/id=='101'", "/response/docs/[1]/id=='100'");
}

