// parsing performance test
// Run from command line with ant test -Dtestcase=TestSolrQueryParser -Dtestmethod=testParsingPerformance -Dtests.asserts=false 2>/dev/null | grep QPS
@Test
public void testParsingPerformance() throws Exception {
    String[] args = { "-queries", "100", "-iter", "1000", "-clauses", "100", "-format", "term%d", "-seed", "0" };
    args = new String[] { "-queries", "1000", "-iter", "2000", "-clauses", "10", "-format", "term%d", "-seed", "0" };
    // args = new String[] {"-queries","1000" ,"-iter","1000000000", "-clauses","10", "-format","term%d", "-seed","0"};
    boolean assertOn = false;
    assert assertOn = true;
    if (assertOn) {
        // System.out.println("WARNING! Assertions are enabled!!!! Will only execute small run.  Change with -Dtests.asserts=false");
        args = new String[] { "-queries", "10", "-iter", "2", "-clauses", "20", "-format", "term%d", "-seed", "0" };
    }
    int iter = 1000;
    int numQueries = 100;
    int maxClauses = 5;
    int maxTerm = 10000000;
    String format = "term%d";
    String field = "foo_s";
    long seed = 0;
    boolean isFilter = true;
    boolean rewrite = false;
    String otherStuff = "";
    for (int i = 0; i < args.length; i++) {
        String a = args[i];
        if ("-queries".equals(a)) {
            numQueries = Integer.parseInt(args[++i]);
        } else if ("-iter".equals(a)) {
            iter = Integer.parseInt(args[++i]);
        } else if ("-clauses".equals(a)) {
            maxClauses = Integer.parseInt(args[++i]);
        } else if ("-format".equals(a)) {
            format = args[++i];
        } else if ("-seed".equals(a)) {
            seed = Long.parseLong(args[++i]);
        } else {
            otherStuff = otherStuff + " " + a;
        }
    }
    Random r = new Random(seed);
    String[] queries = new String[numQueries];
    for (int i = 0; i < queries.length; i++) {
        StringBuilder sb = new StringBuilder();
        boolean explicitField = r.nextInt(5) == 0;
        if (!explicitField) {
            sb.append(field + ":(");
        }
        sb.append(otherStuff).append(" ");
        // TODO: query parse can't parse () for some reason???
        int nClauses = r.nextInt(maxClauses) + 1;
        for (int c = 0; c < nClauses; c++) {
            String termString = String.format(Locale.US, format, r.nextInt(maxTerm));
            if (explicitField) {
                sb.append(field).append(':');
            }
            sb.append(termString);
            sb.append(' ');
        }
        if (!explicitField) {
            sb.append(")");
        }
        queries[i] = sb.toString();
        // System.out.println(queries[i]);
    }
    SolrQueryRequest req = req();
    long start = System.nanoTime();
    int ret = 0;
    for (int i = 0; i < iter; i++) {
        for (String qStr : queries) {
            QParser parser = QParser.getParser(qStr, req);
            parser.setIsFilter(isFilter);
            Query q = parser.getQuery();
            if (rewrite) {
                // TODO: do rewrite
            }
            // use the query somehow
            ret += q.getClass().hashCode();
        }
    }
    long end = System.nanoTime();
    System.out.println((assertOn ? "WARNING, assertions enabled. " : "") + "ret=" + ret + " Parser QPS:" + ((long) numQueries * iter) * 1000000000 / (end - start));
    req.close();
}

/**
 * Test standard query parsers registered in {@link org.apache.solr.search.QParserPlugin#standardPlugins}
 * have NAME field which is final, static, and matches the registered name.
 */
@Test
public void testRegisteredName() throws Exception {
    List<String> notStatic = new ArrayList<>(QParserPlugin.standardPlugins.size());
    List<String> notFinal = new ArrayList<>(QParserPlugin.standardPlugins.size());
    List<String> mismatch = new ArrayList<>(QParserPlugin.standardPlugins.size());
    for (Map.Entry<String, Class<? extends QParserPlugin>> pair : QParserPlugin.standardPlugins.entrySet()) {
        String regName = pair.getKey();
        Class<? extends QParserPlugin> clazz = pair.getValue();
        Field nameField = clazz.getField(FIELD_NAME);
        int modifiers = nameField.getModifiers();
        if (!Modifier.isFinal(modifiers)) {
            notFinal.add(clazz.getName());
        }
        if (!Modifier.isStatic(modifiers)) {
            notStatic.add(clazz.getName());
        } else if (!regName.equals(nameField.get(null))) {
            mismatch.add(regName + " != " + nameField.get(null) + "(" + clazz.getName() + ")");
        }
    }
    assertTrue("All standard QParsers must have final NAME, broken: " + notFinal, notFinal.isEmpty());
    assertTrue("All standard QParsers must have static NAME, broken: " + notStatic, notStatic.isEmpty());
    assertTrue("All standard QParsers must be registered using NAME, broken: " + mismatch, mismatch.isEmpty());
    assertTrue("DEFAULT_QTYPE is not in the standard set of registered names: " + QParserPlugin.DEFAULT_QTYPE, QParserPlugin.standardPlugins.keySet().contains(QParserPlugin.DEFAULT_QTYPE));
}

