    // test big offset into each group
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "rows", "2", "group.limit", "3", "group.offset", "10"), "/grouped=={'" + f + "':{'matches':10,'groups':[" + "{'groupValue':1,'doclist':{'numFound':3,'start':10,'docs':[]}}," + "{'groupValue':3,'doclist':{'numFound':2,'start':10,'docs':[]}}" + "]}}");
    // test adding in scores
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id,score", "rows", "2", "group.limit", "2", "indent", "off"), "/grouped/" + f + "/groups==" + "[" + "{'groupValue':1,'doclist':{'numFound':3,'start':0,'maxScore':10.0,'docs':[{'id':'8','score':10.0},{'id':'10','score':3.0}]}}," + "{'groupValue':3,'doclist':{'numFound':2,'start':0,'maxScore':7.0,'docs':[{'id':'3','score':7.0},{'id':'6','score':2.0}]}}" + "]");
    // test function (functions are currently all float - this may change)
    String func = "add(" + f + "," + f + ")";
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.func", func, "fl", "id", "rows", "2"), "/grouped=={'" + func + "':{'matches':10,'groups':[" + "{'groupValue':2.0,'doclist':{'numFound':3,'start':0,'docs':[{'id':'8'}]}}," + "{'groupValue':6.0,'doclist':{'numFound':2,'start':0,'docs':[{'id':'3'}]}}" + "]}}");
    // test that faceting works with grouping
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "facet", "true", "facet.field", f), "/grouped/" + f + "/matches==10", "/facet_counts/facet_fields/" + f + "==['1',3, '2',3, '3',2, '4',1, '5',1]");
    // test that grouping works with highlighting
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "hl", "true", "hl.fl", f), "/grouped/" + f + "/matches==10", "/highlighting=={'_ORDERED_':'', '8':{},'3':{},'4':{},'1':{},'2':{}}");
    // test that grouping works with debugging
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "debugQuery", "true"), "/grouped/" + f + "/matches==10", "/debug/explain/8==", "/debug/explain/2==");
    ///////////////////////// group.query
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.query", "id:[2 TO 5]", "fl", "id", "group.limit", "3"), "/grouped=={'id:[2 TO 5]':{'matches':10," + "'doclist':{'numFound':4,'start':0,'docs':[{'id':'3'},{'id':'4'},{'id':'2'}]}}}");
    // group.query that matches nothing
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.query", "id:[2 TO 5]", "group.query", "id:1000", "fl", "id", "group.limit", "3"), "/grouped/id:[2 TO 5]=={'matches':10,'doclist':{'numFound':4,'start':0,'docs':[{'id':'3'},{'id':'4'},{'id':'2'}]}}", "/grouped/id:1000=={'matches':10,'doclist':{'numFound':0,'start':0,'docs':[]}}");
    // group.query and offset
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.query", "id:[2 TO 5]", "fl", "id", "group.limit", "3", "group.offset", "2"), "/grouped=={'id:[2 TO 5]':{'matches':10," + "'doclist':{'numFound':4,'start':2,'docs':[{'id':'2'},{'id':'5'}]}}}");
    // group.query and big offset
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.query", "id:[2 TO 5]", "fl", "id", "group.limit", "3", "group.offset", "10"), "/grouped=={'id:[2 TO 5]':{'matches':10," + "'doclist':{'numFound':4,'start':10,'docs':[]}}}");
    ///////////////////////// group.query as main result
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.query", "id:[2 TO 5]", "fl", "id", "rows", "3", "group.main", "true"), "/response=={'numFound':4,'start':0,'docs':[{'id':'3'},{'id':'4'},{'id':'2'}]}");
    // group.query and offset
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.query", "id:[2 TO 5]", "fl", "id", "rows", "3", "start", "2", "group.main", "true"), "/response=={'numFound':4,'start':2,'docs':[{'id':'2'},{'id':'5'}]}");
    // group.query and big offset
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.query", "id:[2 TO 5]", "fl", "id", "rows", "3", "start", "10", "group.main", "true"), "/response=={'numFound':4,'start':10,'docs':[]}");
    // multiple at once
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.query", "id:[2 TO 5]", "group.query", "id:[5 TO 5]", "group.field", f, "rows", "1", "fl", "id", "group.limit", "2"), "/grouped/id:[2 TO 5]=={'matches':10,'doclist':{'numFound':4,'start':0,'docs':[{'id':'3'},{'id':'4'}]}}", "/grouped/id:[5 TO 5]=={'matches':10,'doclist':{'numFound':1,'start':0,'docs':[{'id':'5'}]}}", "/grouped/" + f + "=={'matches':10,'groups':[{'groupValue':1,'doclist':{'numFound':3,'start':0,'docs':[{'id':'8'},{'id':'10'}]}}]}");
    ///////////////////////// group.field as main result
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "group.main", "true"), "/response=={'numFound':10,'start':0,'docs':[{'id':'8'},{'id':'3'},{'id':'4'},{'id':'1'},{'id':'2'}]}");
    // test that rows limits #docs
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "rows", "3", "group.main", "true"), "/response=={'numFound':10,'start':0,'docs':[{'id':'8'},{'id':'3'},{'id':'4'}]}");
    // small  offset
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "rows", "2", "start", "1", "group.main", "true"), "/response=={'numFound':10,'start':1,'docs':[{'id':'3'},{'id':'4'}]}");
    // large offset
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "rows", "2", "start", "20", "group.main", "true"), "/response=={'numFound':10,'start':20,'docs':[]}");
    // group.limit>1
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "rows", "3", "group.limit", "2", "group.main", "true"), "/response=={'numFound':10,'start':0,'docs':[{'id':'8'},{'id':'10'},{'id':'3'}]}");
    // group.limit>1 with start>0
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "rows", "3", "start", "1", "group.limit", "2", "group.main", "true"), "/response=={'numFound':10,'start':1,'docs':[{'id':'10'},{'id':'3'},{'id':'6'}]}");
    ///////////////////////// group.format == simple
    assertJQ(req("fq", filt, "q", "{!func}" + f2, "group", "true", "group.field", f, "fl", "id", "rows", "3", "start", "1", "group.limit", "2", "group.format", "simple"), "/grouped/foo_i=={'matches':10,'doclist':" + "{'numFound':10,'start':1,'docs':[{'id':'10'},{'id':'3'},{'id':'6'}]}}");
    //////////////////////// grouping where main query matches nothing
    assertJQ(req("fq", filt, "q", "bogus_s:nothing", "group", "true", "group.field", f, "fl", "id", "group.limit", "2", "group.format", "simple"), "/grouped/foo_i=={'matches':0,'doclist':{'numFound':0,'start':0,'docs':[]}}");
    assertJQ(req("fq", filt, "q", "bogus_s:nothing", "group", "true", "group.query", "id:[2 TO 5]", "group.query", "id:[5 TO 5]", "group.field", f, "rows", "1", "fl", "id", "group.limit", "2"), "/grouped/id:[2 TO 5]=={'matches':0,'doclist':{'numFound':0,'start':0,'docs':[]}}", "/grouped/id:[5 TO 5]=={'matches':0,'doclist':{'numFound':0,'start':0,'docs':[]}}", "/grouped/" + f + "=={'matches':0,'groups':[]}");
    assertJQ(req("fq", filt, "q", "bogus_s:nothing", "group", "true", "group.query", "id:[2 TO 5]", "group.query", "id:1000", "fl", "id", "group.limit", "3"), "/grouped/id:[2 TO 5]=={'matches':0,'doclist':{'numFound':0,'start':0,'docs':[]}}", "/grouped/id:1000=={'matches':0,'doclist':{'numFound':0,'start':0,'docs':[]}}");
}

@Test
public void testRandomGrouping() throws Exception {
    /**
     *     updateJ("{\"add\":{\"doc\":{\"id\":\"77\"}}}", params("commit","true"));
     *     assertJQ(req("q","id:77"), "/response/numFound==1");
     *
     *     Doc doc = createDocObj(types);
     *     updateJ(toJSON(doc), params("commit","true"));
     *
     *     assertJQ(req("q","id:"+doc.id), "/response/numFound==1");
     */
    // make >0 to enable test
    int indexIter = atLeast(10);
    int queryIter = atLeast(50);
    while (--indexIter >= 0) {
        int indexSize = random().nextInt(25 * RANDOM_MULTIPLIER);
        //indexSize=2;
        List<FldType> types = new ArrayList<>();
        types.add(new FldType("id", ONE_ONE, new SVal('A', 'Z', 4, 4)));
        // field used to score
        types.add(new FldType("score_f", ONE_ONE, new FVal(1, 100)));
        types.add(new FldType("foo_i", ZERO_ONE, new IRange(0, indexSize)));
        types.add(new FldType(FOO_STRING_FIELD, ONE_ONE, new SVal('a', 'z', 1, 2)));
        types.add(new FldType(SMALL_STRING_FIELD, ZERO_ONE, new SVal('a', (char) ('c' + indexSize / 10), 1, 1)));
        types.add(new FldType(SMALL_INT_FIELD, ZERO_ONE, new IRange(0, 5 + indexSize / 10)));
        clearIndex();
        Map<Comparable, Doc> model = indexDocs(types, null, indexSize);
        //System.out.println("############### model=" + model);
        // test with specific docs
        if (false) {
            clearIndex();
            model.clear();
            Doc d1 = createDoc(types);
            d1.getValues(SMALL_STRING_FIELD).set(0, "c");
            d1.getValues(SMALL_INT_FIELD).set(0, 5);
            d1.order = 0;
            updateJ(toJSON(d1), params("commit", "true"));
            model.put(d1.id, d1);
            d1 = createDoc(types);
            d1.getValues(SMALL_STRING_FIELD).set(0, "b");
            d1.getValues(SMALL_INT_FIELD).set(0, 5);
            d1.order = 1;
            updateJ(toJSON(d1), params("commit", "false"));
            model.put(d1.id, d1);
            d1 = createDoc(types);
            d1.getValues(SMALL_STRING_FIELD).set(0, "c");
            d1.getValues(SMALL_INT_FIELD).set(0, 5);
            d1.order = 2;
            updateJ(toJSON(d1), params("commit", "false"));
            model.put(d1.id, d1);
            d1 = createDoc(types);
            d1.getValues(SMALL_STRING_FIELD).set(0, "c");
            d1.getValues(SMALL_INT_FIELD).set(0, 5);
            d1.order = 3;
            updateJ(toJSON(d1), params("commit", "false"));
            model.put(d1.id, d1);
            d1 = createDoc(types);
            d1.getValues(SMALL_STRING_FIELD).set(0, "b");
            d1.getValues(SMALL_INT_FIELD).set(0, 2);
            d1.order = 4;
            updateJ(toJSON(d1), params("commit", "true"));
            model.put(d1.id, d1);
        }
        for (int qiter = 0; qiter < queryIter; qiter++) {
            String groupField = types.get(random().nextInt(types.size())).fname;
            int rows = random().nextInt(10) == 0 ? random().nextInt(model.size() + 2) : random().nextInt(11) - 1;
            // pick a small start normally for better coverage
            int start = random().nextInt(5) == 0 ? random().nextInt(model.size() + 2) : random().nextInt(5);
            int group_limit = random().nextInt(10) == 0 ? random().nextInt(model.size() + 2) : random().nextInt(11) - 1;
            // pick a small start normally for better coverage
            int group_offset = random().nextInt(10) == 0 ? random().nextInt(model.size() + 2) : random().nextInt(2);
            IndexSchema schema = h.getCore().getLatestSchema();
            String[] stringSortA = new String[1];
            Comparator<Doc> sortComparator = createSort(schema, types, stringSortA);
            String sortStr = stringSortA[0];
            Comparator<Doc> groupComparator = random().nextBoolean() ? sortComparator : createSort(schema, types, stringSortA);
            String groupSortStr = stringSortA[0];
            // since groupSortStr defaults to sortStr, we need to normalize null to "score desc" if
            // sortStr != null.
            if (groupSortStr == null && groupSortStr != sortStr) {
                groupSortStr = "score desc";
            }
            // Test specific case
            if (false) {
                groupField = SMALL_INT_FIELD;
                sortComparator = createComparator(Arrays.asList(createComparator(SMALL_STRING_FIELD, true, true, false, true)));
                sortStr = SMALL_STRING_FIELD + " asc";
                groupComparator = createComparator(Arrays.asList(createComparator(SMALL_STRING_FIELD, true, true, false, false)));
                groupSortStr = SMALL_STRING_FIELD + " asc";
                rows = 1;
                start = 0;
                group_offset = 1;
                group_limit = 1;
            }
            Map<Comparable, Grp> groups = groupBy(model.values(), groupField);
            // first sort the docs in each group
            for (Grp grp : groups.values()) {
                Collections.sort(grp.docs, groupComparator);
            }
            // now sort the groups
            // if sort != group.sort, we need to find the max doc by "sort"
            if (groupComparator != sortComparator) {
                for (Grp grp : groups.values()) grp.setMaxDoc(sortComparator);
            }
            List<Grp> sortedGroups = new ArrayList<>(groups.values());
            Collections.sort(sortedGroups, groupComparator == sortComparator ? createFirstDocComparator(sortComparator) : createMaxDocComparator(sortComparator));
            boolean includeNGroups = random().nextBoolean();
            Object modelResponse = buildGroupedResult(schema, sortedGroups, start, rows, group_offset, group_limit, includeNGroups);
            boolean truncateGroups = random().nextBoolean();
            Map<String, Integer> facetCounts = new TreeMap<>();
            if (truncateGroups) {
                for (Grp grp : sortedGroups) {
                    Doc doc = grp.docs.get(0);
                    if (doc.getValues(FOO_STRING_FIELD) == null) {
                        continue;
                    }
                    String key = doc.getFirstValue(FOO_STRING_FIELD).toString();
                    boolean exists = facetCounts.containsKey(key);
                    int count = exists ? facetCounts.get(key) : 0;
                    facetCounts.put(key, ++count);
                }
            } else {
                for (Doc doc : model.values()) {
                    if (doc.getValues(FOO_STRING_FIELD) == null) {
                        continue;
                    }
                    for (Comparable field : doc.getValues(FOO_STRING_FIELD)) {
                        String key = field.toString();
                        boolean exists = facetCounts.containsKey(key);
                        int count = exists ? facetCounts.get(key) : 0;
                        facetCounts.put(key, ++count);
                    }
                }
            }
            List<Comparable> expectedFacetResponse = new ArrayList<>();
            for (Map.Entry<String, Integer> stringIntegerEntry : facetCounts.entrySet()) {
                expectedFacetResponse.add(stringIntegerEntry.getKey());
                expectedFacetResponse.add(stringIntegerEntry.getValue());
            }
            int randomPercentage = random().nextInt(101);
            // TODO: create a random filter too
            SolrQueryRequest req = req("group", "true", "wt", "json", "indent", "true", "echoParams", "all", "q", "{!func}score_f", "group.field", groupField, sortStr == null ? "nosort" : "sort", sortStr == null ? "" : sortStr, (groupSortStr == null || groupSortStr == sortStr) ? "noGroupsort" : "group.sort", groupSortStr == null ? "" : groupSortStr, "rows", "" + rows, "start", "" + start, "group.offset", "" + group_offset, "group.limit", "" + group_limit, GroupParams.GROUP_CACHE_PERCENTAGE, Integer.toString(randomPercentage), GroupParams.GROUP_TOTAL_COUNT, includeNGroups ? "true" : "false", "facet", "true", "facet.sort", "index", "facet.limit", "-1", "facet.field", FOO_STRING_FIELD, // to avoid FC insanity
            GroupParams.GROUP_TRUNCATE, // to avoid FC insanity
            truncateGroups ? "true" : "false", // to avoid FC insanity
            "facet.mincount", // to avoid FC insanity
            "1", // to avoid FC insanity
            "facet.method", // to avoid FC insanity
            "fcs");
            String strResponse = h.query(req);
            Object realResponse = ObjectBuilder.fromJSON(strResponse);
            String err = JSONTestUtil.matchObj("/grouped/" + groupField, realResponse, modelResponse);
            if (err != null) {
                log.error("GROUPING MISMATCH: " + err + "\n\trequest=" + req + "\n\tresult=" + strResponse + "\n\texpected=" + JSONUtil.toJSON(modelResponse) + "\n\tsorted_model=" + sortedGroups);
                // re-execute the request... good for putting a breakpoint here for debugging
                String rsp = h.query(req);
                fail(err);
            }
            // assert post / pre grouping facets
            err = JSONTestUtil.matchObj("/facet_counts/facet_fields/" + FOO_STRING_FIELD, realResponse, expectedFacetResponse);
            if (err != null) {
                log.error("GROUPING MISMATCH: " + err + "\n\trequest=" + req + "\n\tresult=" + strResponse + "\n\texpected=" + JSONUtil.toJSON(expectedFacetResponse));
                // re-execute the request... good for putting a breakpoint here for debugging
                h.query(req);
                fail(err);
            }
        }
        // end query iter
    }
    // end index iter
}

