    removeList = new ArrayList<String>();
    removeList.add("bbb");
    removeList.add("ccc");
    //behavior when hitting Solr through ZK
    doc.setField("cat", ImmutableMap.of("remove", removeList));
    assertU(adoc(doc));
    assertU(commit());
    assertQ(req("q", "cat:*", "indent", "true"), "//result[@numFound = '4']");
    assertQ(req("q", "cat:bbb", "indent", "true"), "//result[@numFound = '1']");
