@Test
public void testAtomicUpdatesOnNonStoredDocValuesCopyField() throws Exception {
    assertU(adoc(sdoc("id", 101, "title", "title2", "single_i_dvn", 100)));
    assertU(adoc(sdoc("id", 102, "title", "title3", "single_d_dvn", 3.14)));
