    // Do each one twice... the first time it will be retrieved from the index, and the second time from the transaction log.
    for (int i = 0; i < 2; i++) {
        assertU(adoc(sdoc("id", 101, "title", ImmutableMap.of("set", "newtitle2"), "single_i_dvn", ImmutableMap.of("inc", 1))));
        assertU(adoc(sdoc("id", 102, "title", ImmutableMap.of("set", "newtitle3"), "single_d_dvn", ImmutableMap.of("inc", 1))));
        assertU(adoc(sdoc("id", 103, "single_i_dvn", ImmutableMap.of("inc", 1))));
    }
