    assertJQ(req("q", "id:102"), 1e-4, "/response/docs/[0]/id==102", "/response/docs/[0]/title/[0]=='newtitle3'", "/response/docs/[0]/single_d_dvn==5.14");
    assertJQ(req("q", "id:103"), "/response/docs/[0]/id==103", "/response/docs/[0]/single_s_dvn=='abc'", "/response/docs/[0]/single_i_dvn==3");
    // test that non stored docvalues was carried forward for a non-docvalue update
    assertU(adoc(sdoc("id", 103, "single_s_dvn", ImmutableMap.of("set", "abcupdate"), "single_i_dvn", ImmutableMap.of("set", 5))));
    assertU(commit());
    assertJQ(req("q", "id:103"), "/response/docs/[0]/id==103", "/response/docs/[0]/single_s_dvn=='abcupdate'", "/response/docs/[0]/single_i_dvn==5");
}

