                    } catch (Exception e) {
                        throw new RuntimeException(e);
                    }
                }
            }
        };
        threads2[i].setName("testThread2-" + i);
    }
    for (int i = 0; i < threads.length; i++) {
        threads[i].start();
    }
    for (int i = 0; i < threads2.length; i++) {
        threads2[i].start();
    }
    for (int i = 0; i < threads.length; i++) {
        threads[i].join();
    }
    for (int i = 0; i < threads2.length; i++) {
        threads2[i].join();
    }
