        // 0001 1000 -> 0x18 -> 24
        // 0000 0000 -> 0x00 -> 0
        // 0000 1110 -> 0x0D -> 14
        // 0000 0000 -> 0x00 -> 0
        // 0000 1000 -> 0x08 -> 8
        final byte[] bytes = serializer.getBytes();
