    q.add(new TermQuery(new Term("a", "d")), Occur.SHOULD);
    SolrPluginUtils.setMinShouldMatch(q, "0");
    assertEquals(0, q.build().getMinimumNumberShouldMatch());
    SolrPluginUtils.setMinShouldMatch(q, "1");
