                assertEquals("hello4", rs.getString(1));
                //sum(a_f)
                assertEquals(11, rs.getDouble("EXPR$1"), 0);
                assertEquals(11, rs.getDouble(2), 0);
                assertFalse(rs.next());
            }
        }
    }
}

