        Thread.sleep(250);
        rsp = client.query(new SolrQuery("id:id3"));
        if (rsp.getResults().getNumFound() == 0) {
            return;
        }
    } while (!timeout.hasTimedOut());
    Assert.fail("commitWithin failed to commit");
