@Test
public void testSimpleCollectionWatch() throws Exception {
    CloudSolrClient client = cluster.getSolrClient();
    CollectionAdminRequest.createCollection("testcollection", "config", 4, 1).processAndWait(client, MAX_WAIT_TIMEOUT);
    client.waitForState("testcollection", MAX_WAIT_TIMEOUT, TimeUnit.SECONDS, (n, c) -> DocCollection.isFullyActive(n, c, 4, 1));
    // shutdown a node and check that we get notified about the change
    final CountDownLatch latch = new CountDownLatch(1);
    client.registerCollectionStateWatcher("testcollection", (liveNodes, collectionState) -> {
        int nodeCount = 0;
        log.info("State changed: {}", collectionState);
        for (Slice slice : collectionState) {
            for (Replica replica : slice) {
                if (replica.isActive(liveNodes))
                    nodeCount++;
            }
        }
        if (nodeCount == 3) {
            latch.countDown();
            return true;
        }
        return false;
    });
    cluster.stopJettySolrRunner(random().nextInt(cluster.getJettySolrRunners().size()));
    assertTrue("CollectionStateWatcher was never notified of cluster change", latch.await(MAX_WAIT_TIMEOUT, TimeUnit.SECONDS));
    waitFor("CollectionStateWatcher wasn't cleared after completion", 1, TimeUnit.SECONDS, () -> client.getZkStateReader().getStateWatchers("testcollection").isEmpty());
}

